from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents on one line item, rounded half-even.

    Call per line item and sum the results; never round an invoice total.
    """
    if not isinstance(rate, Decimal):
        rate = Decimal(str(rate))
    tax = (Decimal(amount_cents) * rate).quantize(Decimal(1), rounding=ROUND_HALF_EVEN)
    return int(tax)
